package db

import (
	"context"
	"fmt"
	"strconv"
	"strings"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgtype"

	"github.com/tvstore/forgebase-go/internal/core"
)

// newID is a new UUID v7, generated by the application.
func newID() uuid.UUID { return uuid.Must(uuid.NewV7()) }

// amendOf is what makes an insert an amendment: the cancelled document it replaces and its name.
type amendOf struct {
	from string
	name string
}

// newName is the name for a new document. doc has passed validation. An amendment has the name its
// rule gave it (a hook may not change it); the series takes the next number of its counter.
func newName(ctx context.Context, c Queryer, doctype *core.DocType, doc *core.Document, id uuid.UUID, amend *amendOf) (string, error) {
	naming := func(format string, args ...any) error {
		return &Error{Kind: ErrNaming, Message: fmt.Sprintf(format, args...)}
	}
	if amend != nil {
		if doc.Name != amend.name {
			return "", naming("an amended document is named `%s` and the name cannot be changed", amend.name)
		}
		return amend.name, nil
	}
	switch doctype.Naming.Kind {
	case core.NamingField:
		field := doctype.Naming.Field
		v := doc.Values[field]
		if v.Kind != core.KindText {
			return "", naming("field `%s` must hold the document name", field)
		}
		if doc.Name != "" && doc.Name != v.Text {
			return "", naming("the given name differs from the value of naming field `%s`", field)
		}
		return v.Text, nil
	case core.NamingSeries:
		if doc.Name != "" {
			return "", naming("DocType `%s` uses a naming series: the name is generated and cannot be given", doctype.Name)
		}
		return nextSeriesName(ctx, c, doctype.Naming.Series)
	}
	if doc.Name != "" {
		return "", naming("DocType `%s` uses random naming: the name is generated and cannot be given", doctype.Name)
	}
	return id.String(), nil
}

// seriesSQL is the counter statement: it takes (creating it if needed) the row of the prefix, $1,
// and increments it. The row lock lasts until the transaction ends.
const seriesSQL = "INSERT INTO fb_series (prefix, current) VALUES ($1::text, 1) " +
	"ON CONFLICT (prefix) DO UPDATE SET current = fb_series.current + 1 RETURNING current"

// nextSeriesName is the next name of a series: the prefix is rendered with the UTC date of the
// transaction, the counter of that prefix is incremented in the caller's transaction and the number
// rendered.
func nextSeriesName(ctx context.Context, c Queryer, pattern *core.SeriesPattern) (string, error) {
	var date pgtype.Date
	if err := c.QueryRow(ctx, "SELECT (now() AT TIME ZONE 'UTC')::date").Scan(&date); err != nil {
		return "", wrap(err)
	}
	prefix := pattern.Prefix(date.Time)
	var number int64
	if err := c.QueryRow(ctx, seriesSQL, prefix).Scan(&number); err != nil {
		return "", wrap(err)
	}
	if number < 0 {
		return "", &Error{Kind: ErrNaming, Message: fmt.Sprintf(
			"the counter of series prefix `%s` holds %d, which is not a valid number", prefix, number)}
	}
	return pattern.Render(date.Time, uint64(number)), nil
}

// amendedName is the name of the amendment of a cancelled document, see Amend. amendedFrom says
// whether the cancelled document is itself an amendment.
func amendedName(name string, amendedFrom bool) string {
	if amendedFrom {
		if i := strings.LastIndexByte(name, '-'); i >= 0 {
			root, digits := name[:i], name[i+1:]
			if digits != "" && allASCIIDigits(digits) {
				if n, err := strconv.ParseUint(digits, 10, 64); err == nil && n != 1<<64-1 {
					return fmt.Sprintf("%s-%d", root, n+1)
				}
			}
		}
	}
	return name + "-1"
}

func allASCIIDigits(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}
